pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address user, uint256 amount, address rewardToken) public {
        vm.assume(user != address(0));
        vm.assume(rewardToken != address(0) && rewardToken != address(c.stakingToken()));
        amount = bound(amount, 1, 1e30);

        // Pre-state: totalSupply() and sum of balances before addReward
        uint256 totalBefore = c.totalSupply();

        // Simulate staking by transferring staking token to c and calling stakeFor
        deal(address(c.stakingToken()), user, amount);
        vm.prank(user);
        address(c.stakingToken()).call(abi.encodeWithSignature("approve(address,uint256)", address(c), amount));
        vm.prank(user);
        c.stakeFor(user, amount);

        uint256 totalAfterStake = c.totalSupply();
        uint256 userBalance = c.balanceOf(user);
        // totalSupply should equal sum of balances (only user has stake)
        assertTrue(totalAfterStake == userBalance, "totalSupply should equal user balance after stake");

        // Now call addReward – this should not change totalSupply
        c.addReward(rewardToken);
        uint256 totalAfterAdd = c.totalSupply();
        assertTrue(totalAfterAdd == totalAfterStake, "totalSupply unchanged after addReward");
    }
}

