pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));

        // Record state before call
        uint256 tokenCountBefore = c.rewardTokens().length;

        // Call addReward and capture revert status
        (bool success, ) = address(c).call(abi.encodeWithSignature("addReward(address)", rewardToken));

        if (success) {
            // If succeeded, rewardToken must be added to rewardTokens and lastUpdateTime must be set
            assertTrue(c.rewardTokens().length == tokenCountBefore + 1);
            assertTrue(c.rewardTokens(c.rewardTokens().length - 1) == rewardToken);
            ( , , uint40 lastUpdateTime, ) = c.rewardData(rewardToken);
            assertTrue(lastUpdateTime == uint40(block.timestamp));
        } else {
            // If reverted, rewardToken must NOT be added to rewardTokens
            assertTrue(c.rewardTokens().length == tokenCountBefore);
        }
    }
}

